    left_clock = clock.left < clock.right
    top_clock = clock.lower < clock.upper

    next_to_white = []
    for white in white_patches:
        if left_clock:
            if white.right <= clock.left:
                next_to_white.append(white)
        else:
            if white.left >= clock.right:
                next_to_white.append(white)

